#!/usr/bin/env bash
# Run from qualified source tree; /tmp fixture contains the archived src files.
source /tmp/gpui-native-env.sh
rustc --edition=2024 --crate-type rlib --crate-name gpui_reactivity_core -C opt-level=3 -C debug-assertions=no reactivity/crates/core/src/lib.rs -o /tmp/gpui-presented-basis-asm/libgpui_reactivity_core-x86_64.rlib
rustc --edition=2024 --crate-type lib --crate-name presented_basis_asm_audit --emit asm -C opt-level=3 -C debug-assertions=no -L dependency=/tmp/gpui-presented-basis-target/debug/deps --extern gpui_reactivity_core=/tmp/gpui-presented-basis-asm/libgpui_reactivity_core-x86_64.rlib /tmp/gpui-presented-basis-asm/src/lib.rs -o /tmp/gpui-presented-basis-asm/x86_64.s
rustc --edition=2024 --crate-type rlib --crate-name gpui_reactivity_core --target aarch64-apple-darwin -C opt-level=3 -C debug-assertions=no -L dependency=/tmp/gpui-presented-basis-target/aarch64-apple-darwin/debug/deps --extern std=/tmp/gpui-presented-basis-target/aarch64-apple-darwin/debug/deps/libstd-82a9bcb33cb6b3d9.rmeta reactivity/crates/core/src/lib.rs -o /tmp/gpui-presented-basis-asm/libgpui_reactivity_core.rlib
rustc --edition=2024 --crate-type lib --crate-name presented_basis_asm_audit --target aarch64-apple-darwin --emit asm -C opt-level=3 -C debug-assertions=no -L dependency=/tmp/gpui-presented-basis-target/aarch64-apple-darwin/debug/deps --extern std=/tmp/gpui-presented-basis-target/aarch64-apple-darwin/debug/deps/libstd-82a9bcb33cb6b3d9.rmeta --extern gpui_reactivity_core=/tmp/gpui-presented-basis-asm/libgpui_reactivity_core.rlib /tmp/gpui-presented-basis-asm/src/lib.rs -o /tmp/gpui-presented-basis-asm/aarch64-apple-darwin.s
